function useRevealAnimations() {
  useEffect(() => {
    const revealItems = document.querySelectorAll(
      ".reveal, .reveal-up, .reveal-left, .reveal-scale, .story-chapter, .glass"
    );

    revealItems.forEach((el, index) => {
      if (!el.classList.contains("story-chapter") && !el.classList.contains("glass")) {
        el.classList.add("reveal-ready");
      } else {
        el.classList.add("reveal-ready");
      }
      if (!el.style.getPropertyValue("--reveal-delay")) {
        el.style.setProperty("--reveal-delay", `${Math.min(index * 55, 420)}ms`);
      }
    });

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add("is-visible");
            observer.unobserve(entry.target);
          }
        });
      },
      { threshold: 0.12, rootMargin: "0px 0px -55px 0px" }
    );

    revealItems.forEach((el) => observer.observe(el));

    const onScroll = () => {
      const max = document.documentElement.scrollHeight - window.innerHeight;
      const progress = max > 0 ? window.scrollY / max : 0;
      document.documentElement.style.setProperty("--scroll-progress", progress.toString());

      document.querySelectorAll("[data-parallax]").forEach((el) => {
        const speed = Number(el.dataset.parallax || 0.08);
        const rect = el.getBoundingClientRect();
        const offset = (window.innerHeight / 2 - (rect.top + rect.height / 2)) * speed;
        el.style.setProperty("--parallax-y", `${offset}px`);
      });
    };

    onScroll();
    window.addEventListener("scroll", onScroll, { passive: true });

    return () => {
      observer.disconnect();
      window.removeEventListener("scroll", onScroll);
    };
  }, []);
}

function PeacockFeather({ className = "" }) {
  return <span className={`feather-art ${className}`} aria-hidden="true"><i /><b /><em /><strong /></span>;
}

function FluteIcon() {
  return <span className="flute-art" aria-hidden="true"><i /><i /><i /><i /><i /><b /></span>;
}

function Lotus({ size = "normal" }) {
  return <span className={`lotus ${size}`} aria-hidden="true"><i /><i /><i /><i /><i /><i /><b /></span>;
}

function LoveLetter({ onClose }) {
  return <div className="letter-overlay" role="dialog" aria-modal="true" aria-label="A letter for Krishna">
    <div className="letter-card">
      <button className="letter-close" onClick={onClose} aria-label="Close letter">×</button>
      <div className="letter-mark"><PeacockFeather /></div>
      <label>A LETTER FROM YOUR RADHA</label>
      <h2>To My Krishna</h2>
      <div className="letter-lines">
        <p>My Krishna,</p>
        <p>I made this little Vrindavan because sometimes a normal “I love you” feels far too small.</p>
        <p>If I could keep one thing from every beautiful moment we share, I would keep the way you make me smile without even trying.</p>
        <p>So tonight, beneath this little Janmashtami moon, I just want you to know — you are my favourite person to laugh with, tease, dream with, and come home to.</p>
        <p>Keep your Krishna-like mischief. Keep that smile. Keep being you.</p>
        <p>And whenever life gets loud, come back here for a moment. I’ll always leave a little corner of Vrindavan waiting for you.</p>
        <p className="signature">Always yours,<br /><strong>{FROM_NAME}</strong> ♥</p>
      </div>
    </div>
  </div>;
}

